import { useState, type FormEvent } from "react";

const INK = "#28030F";
const ACCENT = "#FBF582";
const CREAM = "#FBF6EC";

const PILLS = [
  { label: "Look up", icon: "search" as const },
  { label: "Research", icon: "flask" as const },
  { label: "Treat", icon: "pulse" as const },
  { label: "Explain", icon: "bubble" as const },
  { label: "Compare", icon: "swap" as const },
];

function Icon({ name, size = 16 }: { name: "search" | "flask" | "pulse" | "bubble" | "swap" | "calendar" | "sparkle"; size?: number }) {
  const common = { width: size, height: size, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.7, strokeLinecap: "round" as const, strokeLinejoin: "round" as const, "aria-hidden": true };
  switch (name) {
    case "search":
      return (
        <svg {...common}>
          <circle cx="11" cy="11" r="6.5" />
          <path d="M20 20l-4.3-4.3" />
        </svg>
      );
    case "flask":
      return (
        <svg {...common}>
          <path d="M9 2h6M10 2v6.2L4.6 18a2 2 0 0 0 1.8 3h11.2a2 2 0 0 0 1.8-3L14 8.2V2" />
        </svg>
      );
    case "pulse":
      return (
        <svg {...common}>
          <path d="M3 12h4l2-7 4 14 2-7h6" />
        </svg>
      );
    case "bubble":
      return (
        <svg {...common}>
          <path d="M21 11.5a8.4 8.4 0 0 1-8.9 8.5 9 9 0 0 1-3.6-.7L3 21l1.8-5.1A8.4 8.4 0 1 1 21 11.5Z" />
        </svg>
      );
    case "swap":
      return (
        <svg {...common}>
          <path d="M7 7h12l-3.5-3.5M17 17H5l3.5 3.5" />
        </svg>
      );
    case "calendar":
      return (
        <svg {...common}>
          <rect x="3.5" y="5" width="17" height="15.5" rx="2.5" />
          <path d="M8 3v4M16 3v4M3.5 10h17" />
        </svg>
      );
    case "sparkle":
      return (
        <svg {...common} fill="currentColor" stroke="none">
          <path d="M12 2l1.8 5.6L19.5 9l-5.7 1.4L12 16l-1.8-5.6L4.5 9l5.7-1.4L12 2Z" />
        </svg>
      );
  }
}

